package com.vit.archds.entity;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="analysis_jobs",indexes={@Index(name="idx_jobs_project",columnList="project_id"),@Index(name="idx_jobs_status",columnList="status")})
public class AnalysisJob { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true,length=40) private String jobId=UUID.randomUUID().toString(); @ManyToOne(fetch=FetchType.EAGER,optional=false) @JoinColumn(name="project_id") private Project project; @Enumerated(EnumType.STRING) @Column(nullable=false) private JobStatus status=JobStatus.QUEUED; @Column(nullable=false) private int progress=0; @Column(length=100) private String currentStage="QUEUED"; @Column(length=1000) private String message="Analysis queued"; @Column(length=2000) private String errorMessage; @Column(columnDefinition="TEXT") private String pipelineResponseJson; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); private Instant startedAt; private Instant completedAt;
 public AnalysisJob(){} public AnalysisJob(Project p){project=p;} public Long getId(){return id;} public String getJobId(){return jobId;} public Project getProject(){return project;} public JobStatus getStatus(){return status;} public int getProgress(){return progress;} public String getCurrentStage(){return currentStage;} public String getMessage(){return message;} public String getErrorMessage(){return errorMessage;} public String getPipelineResponseJson(){return pipelineResponseJson;} public void setPipelineResponseJson(String v){pipelineResponseJson=v;} public Instant getCreatedAt(){return createdAt;} public Instant getStartedAt(){return startedAt;} public Instant getCompletedAt(){return completedAt;} public void start(){status=JobStatus.RUNNING;startedAt=Instant.now();} public void update(String stage,int p,String msg){currentStage=stage;progress=p;message=msg;} public void complete(){status=JobStatus.COMPLETED;progress=100;currentStage="COMPLETED";completedAt=Instant.now();} public void fail(String e){status=JobStatus.FAILED;errorMessage=e;message="Analysis failed";completedAt=Instant.now();}}
